class Client {
  + NIN
  + TIN
  + Name
  + Address
}

class BicycleModel {
  + Name
  + Type
  + Number_of_gears
}

class Bicycle {
  + Identifying_number
}

class Store {
  + Name
  + Address
}

class Reservation {
  + Pick_up_day
}

class Rental {
  + Return_date
}

Client "1" -- "*" Reservation : makes
BicycleModel "1" -- "*" Reservation : requested_in
Store "1" -- "*" Reservation : pick_up_at

Bicycle "*" -- "1" BicycleModel : is_a_model
Bicycle "1" -- "0..1" Rental : is_rented_in
Client "1" -- "*" Rental : makes
Store "1" -- "*" Rental : pick_up_at
Store "1" -- "*" Rental : return_at

@enduml

